/* Types */
/**  Akun yang sedang login di sebuah forge. */
export type Account = {
	/**
	 *  `"{kind}:{hostname}:{username}"`, misalnya `"github:github.com:octocat"`. Dipakai
	 *  juga sebagai kunci token di keychain.
	 */
	id: string,
	kind: ForgeKind,
	/**  Origin web instance, sama dengan [`ForgeHost::host`]. */
	host: string,
	username: string,
	/**  Nama tampilan; sama dengan `username` bila pengguna tidak mengisinya. */
	displayName: string,
	avatarUrl: string | null,
};

/**  Daftar akun GitHub/GitLab berubah (login atau logout). */
export type AccountsChanged = Record<string, never>;

/**  `code` dipakai UI untuk memilih pesan dan aksi lanjutan (mis. `pushRejected`, `stale`, `untrusted`). */
export type AppError = {
	code: string,
	message: string,
	/**  Mis. stderr git apa adanya. */
	detail: string | null,
};

export type AppInfo = {
	version: string,
	/**  `linux`, `windows`, atau `macos`. */
	platform: string,
	git: GitInfo | null,
	/**  Alasan fitur Git tidak tersedia (git tidak ada atau terlalu lama). */
	gitError: string | null,
	recent: string[],
	settingsPath: string,
	/**  Berkas penimpaan pintasan keyboard milik pengguna. */
	keybindingsPath: string,
	homeDir: string | null,
};

